const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];let activeChat='',allConvs=[];
async function api(url,opts={}){const r=await fetch(url,{headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});const j=await r.json().catch(()=>({}));if(r.status===401){location.href='/login.html';throw new Error('Sesión requerida')}if(!r.ok)throw new Error(j.error||'Error de servidor');return j}
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2500)}
const titles={dashboard:['Resumen','Ventas y atención multicanal en una sola plataforma.'],inbox:['Conversaciones','WhatsApp, Telegram y Messenger en una sola bandeja.'],contacts:['Contactos','CRM sencillo para organizar clientes.'],pipeline:['Oportunidades','Seguimiento visual de ventas.'],products:['Catálogo','Productos, servicios, precios y disponibilidad.'],appointments:['Agenda','Citas y reservas del negocio.'],agent:['Agente IA clásico','Configuración heredada del asistente principal.'],agents:['Agentes IA','Crea y coordina un equipo multiagente especializado.'],channels:['Canales','Conecta los canales de atención.'],rules:['Automatizaciones','Respuestas rápidas antes de invocar la IA.'],marketing:['Growth & Campañas','Captación orgánica y pagada con asistencia de IA.'],landings:['Landing Pages','Crea páginas comerciales premium conectadas al CRM.'],groups:['Grupos & Comunidades','Gestiona comunidades autorizadas y descubre grupos públicos por nicho.'],users:['Equipo','Usuarios, roles y accesos.'],billing:['Plan y pagos','Suscripción, límites y pagos en USDT.'],admin:['Administración Worktic','Usuarios, compras y suscripciones de toda la plataforma.'],setup:['Guías','Instrucciones claras para poner todo en marcha.']};
$$('nav button').forEach(b=>b.onclick=()=>{const v=b.dataset.view;$$('nav button,.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#'+v).classList.add('active');$('#title').textContent=titles[v][0];$('#subtitle').textContent=titles[v][1];if(v==='inbox')loadConvs();if(v==='contacts')loadContacts();if(v==='pipeline')loadOpps();if(v==='agent')loadAgent();if(v==='agents')loadAIAgents();if(v==='channels')loadChannels();if(v==='rules')loadRules();if(v==='marketing')loadMarketing();if(v==='landings')loadLandings();if(v==='groups')loadGroups();if(v==='products')loadProducts();if(v==='appointments')loadAppointments();if(v==='users')loadUsers();if(v==='billing')loadBilling();if(v==='admin')loadAdmin()});
async function loadDashboard(){const [d,h,c]=await Promise.all([api('/api/dashboard'),api('/api/channels/health'),api('/api/channels/connections')]);$('#stats').innerHTML=[['Conversaciones',d.conversations],['Mensajes',d.messages],['Sin leer',d.unread],['Contactos CRM',d.contacts],['Oportunidades',d.open_opportunities],['Valor pipeline','$'+Number(d.pipeline_value||0).toLocaleString()],['Productos',d.products||0],['Citas próximas',d.appointments||0]].map(x=>`<div class="stat"><b>${x[1]}</b><small>${x[0]}</small></div>`).join('');const connected=h.states.connected||0;$('#statusPill').textContent=connected?`${connected} canal(es) conectado(s)`:'Canales pendientes';const by=t=>c.connections.filter(x=>x.type===t&&x.status==='connected').length;$('#channelSummary').innerHTML=`<p>WhatsApp: <b>${by('whatsapp_qr')} conectado(s)</b></p><p>Telegram: <b>${by('telegram')} conectado(s)</b></p><p>Messenger: <b>${by('messenger')} conectado(s)</b></p><p>Aislamiento: <b>tenant + conexión</b></p>`}
async function loadConvs(){allConvs=await api('/api/conversations');renderConvs(allConvs)}function renderConvs(xs){$('#convList').innerHTML=xs.map(c=>`<div class="conv ${c.chat_jid===activeChat?'active':''}" data-chat="${c.chat_jid}"><div class="top"><b>${esc(c.name||c.phone)}</b><span class="badge ${c.channel}">${c.channel==='telegram'?'TG':(c.channel==='messenger'?'MS':'WA')}</span></div><small>${esc(c.last_text||'')}</small>${c.unread?`<b>${c.unread} nuevos</b>`:''}</div>`).join('');$$('.conv').forEach(x=>x.onclick=()=>openChat(x.dataset.chat))}
$('#searchConv').oninput=e=>renderConvs(allConvs.filter(c=>(c.name+c.phone+c.last_text).toLowerCase().includes(e.target.value.toLowerCase())));
async function openChat(chat){activeChat=chat;const c=allConvs.find(x=>x.chat_jid===chat);$('#chatHead').textContent=(c?.name||c?.phone||chat)+' · '+(c?.channel||'');await api('/api/read',{method:'POST',body:JSON.stringify({chat})});const ms=await api('/api/messages?chat='+encodeURIComponent(chat));$('#messages').innerHTML=ms.map(m=>`<div class="msg ${m.direction==='out'?'out':''}">${esc(m.text)}<small>${new Date(m.timestamp).toLocaleString()} · ${m.status}</small></div>`).join('');$('#messages').scrollTop=$('#messages').scrollHeight;renderConvs(allConvs)}
$('#sendForm').onsubmit=async e=>{e.preventDefault();if(!activeChat)return toast('Selecciona una conversación');const text=$('#messageText').value.trim();if(!text)return;try{await api('/api/send',{method:'POST',body:JSON.stringify({chat:activeChat,text})});$('#messageText').value='';await openChat(activeChat);await loadConvs()}catch(e){toast(e.message)}};
let channelPollers={};
async function loadChannels(){
  const d=await api('/api/channels/connections'),h=await api('/api/channels/health');
  $('#channelLimit').textContent=`${d.connections.length} de ${d.max_total} conexiones`;
  $('#channelHealth').innerHTML=[['Conectadas',h.states.connected||0],['Esperando QR',h.states.waiting_qr||0],['Con error',h.states.error||0],['Mensajes aislados',h.messages||0]].map(x=>`<div class="stat"><b>${x[1]}</b><small>${x[0]}</small></div>`).join('');
  $('#channelConnections').innerHTML=d.connections.length?d.connections.map(c=>`<article class="card"><div class="top"><span class="badge ${c.type}">${c.type==='whatsapp_qr'?'WhatsApp':c.type==='telegram'?'Telegram':'Messenger'}</span><span class="pill">${esc(c.status)}</span></div><h3>${esc(c.name)}</h3><p>${c.external_account_id?`Cuenta: <b>${esc(c.external_account_id)}</b>`:'Aún no vinculada'}</p><small>Agente asignado: ${c.assigned_agent_id||'principal'} · ID ${c.id}</small>${c.last_error?`<div class="notice">${esc(c.last_error)}</div>`:''}<div id="qrbox-${c.id}"></div><div class="actions"><button onclick='connectTenantChannel(${JSON.stringify(c)})'>${c.status==='connected'?'Reconfigurar':'Conectar'}</button><button class="secondary" onclick="pauseTenantChannel(${c.id})">Pausar</button><button class="danger" onclick="deleteTenantChannel(${c.id})">Eliminar</button></div></article>`).join(''):'<p>No hay conexiones. Crea el primer canal de este espacio.</p>';
}
$('#refreshChannels').onclick=loadChannels;
$('#newChannel').onclick=()=>modal(`<h2>Nueva conexión aislada</h2><label>Tipo<select id="ccType"><option value="whatsapp_qr">WhatsApp QR</option><option value="telegram">Telegram Bot</option><option value="messenger">Facebook Messenger</option></select></label><label>Nombre<input id="ccName" placeholder="Ej. WhatsApp Ventas"></label><label>Agente ID<input id="ccAgent" type="number" min="0" value="0"></label><div class="notice">El backend valida el límite total y el máximo por tipo de tu plan.</div><div class="actions"><button type="button" id="saveChannel">Crear</button><button value="cancel" class="secondary">Cancelar</button></div>`);document.addEventListener('click',async function h(e){if(e.target?.id!=='saveChannel')return;document.removeEventListener('click',h);try{await api('/api/channels/connections',{method:'POST',body:JSON.stringify({type:$('#ccType').value,name:$('#ccName').value,assigned_agent_id:Number($('#ccAgent').value||0)})});$('#modal').close();loadChannels();toast('Conexión creada')}catch(err){toast(err.message)}});
window.connectTenantChannel=async c=>{
 if(c.type==='whatsapp_qr'){await api('/api/channels/action',{method:'POST',body:JSON.stringify({id:c.id,action:'connect',agent_id:c.assigned_agent_id||0})});toast('Generando QR exclusivo');pollTenantQR(c.id);return}
 const label=c.type==='telegram'?'Token de BotFather':'Page Access Token';const token=prompt(label);if(!token)return;const ext=prompt(c.type==='telegram'?'Usuario del bot, sin @':'Page ID')||'';try{await api('/api/channels/action',{method:'POST',body:JSON.stringify({id:c.id,action:'connect',token,external_id:ext,agent_id:c.assigned_agent_id||0})});toast('Canal conectado');loadChannels()}catch(e){toast(e.message)}
};
async function pollTenantQR(id){clearTimeout(channelPollers[id]);try{const q=await api('/api/channels/qr?id='+id),box=$('#qrbox-'+id);if(box&&q.data_url)box.innerHTML=`<p>Escanea este QR desde el WhatsApp que pertenece a esta empresa:</p><img class="qr" src="${q.data_url}">`;if(q.connected){toast('WhatsApp conectado');loadChannels();return}}catch(e){}channelPollers[id]=setTimeout(()=>pollTenantQR(id),2500)}
window.pauseTenantChannel=async id=>{await api('/api/channels/action',{method:'POST',body:JSON.stringify({id,action:'pause'})});loadChannels()};
window.deleteTenantChannel=async id=>{if(!confirm('¿Eliminar esta conexión y su referencia?'))return;await api('/api/channels/connections?id='+id,{method:'DELETE'});loadChannels()};
async function loadAgent(){const x=await api('/api/agent'),a=x.agent,f=$('#agentForm');for(const k of ['name','company','objective','tone','instructions','knowledge'])f.elements[k].value=a[k]||'';f.elements.enabled.checked=!!a.enabled}
$('#agentForm').onsubmit=async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));d.enabled=f.elements.enabled.checked;try{await api('/api/agent',{method:'PUT',body:JSON.stringify(d)});toast('Agente guardado')}catch(e){toast(e.message)}};
$('#testAgent').onclick=async()=>{const b=$('#testAgent');b.disabled=true;$('#testReply').textContent='Pensando…';try{const x=await api('/api/agent/test',{method:'POST',body:JSON.stringify({text:$('#testPrompt').value})});$('#testReply').textContent=x.reply}catch(e){$('#testReply').textContent=e.message}finally{b.disabled=false}};
async function loadRules(){const xs=await api('/api/rules');$('#rulesList').innerHTML=xs.length?xs.map(r=>`<div class="card"><b>${esc(r.name)}</b><p>${esc(r.keyword)} → ${esc(r.response)}</p><small>${r.enabled?'Activa':'Pausada'}</small> <button onclick="delRule(${r.id})" class="secondary">Eliminar</button></div>`).join(''):'No hay reglas'}
$('#ruleForm').onsubmit=async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));d.enabled=f.elements.enabled.checked;try{await api('/api/rules',{method:'POST',body:JSON.stringify(d)});f.reset();f.elements.enabled.checked=true;loadRules();toast('Regla creada')}catch(e){toast(e.message)}};window.delRule=async id=>{await api('/api/rules?id='+id,{method:'DELETE'});loadRules()};
async function loadContacts(){const xs=await api('/api/crm/contacts');$('#contactsTable').innerHTML=`<table class="table"><tr><th>Nombre</th><th>Teléfono</th><th>Canal</th><th>Etapa</th><th>Etiquetas</th></tr>${xs.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.phone)}</td><td>${esc(x.channel)}</td><td>${esc(x.stage)}</td><td>${esc(x.tags)}</td></tr>`).join('')}</table>`}
$('#newContact').onclick=async()=>{const name=prompt('Nombre del contacto');if(!name)return;const phone=prompt('Teléfono');await api('/api/crm/contacts',{method:'POST',body:JSON.stringify({name,phone,channel:'manual',stage:'Nuevo',tags:'',notes:''})});loadContacts()};
const stages=['Nuevo','Interesado','Calificado','Cotización','Ganado','Perdido'];async function loadOpps(){const xs=await api('/api/crm/opportunities');$('#pipelineBoard').innerHTML=stages.map(s=>`<div class="column"><b>${s}</b>${xs.filter(x=>x.stage===s).map(x=>`<div class="card"><b>${esc(x.title)}</b><p>$${Number(x.value||0).toLocaleString()}</p><small>${esc(x.owner||'Sin asignar')}</small></div>`).join('')}</div>`).join('')}
$('#newOpp').onclick=async()=>{const title=prompt('Nombre de la oportunidad');if(!title)return;const value=Number(prompt('Valor estimado','0')||0);await api('/api/crm/opportunities',{method:'POST',body:JSON.stringify({title,value,stage:'Nuevo',owner:''})});loadOpps()};

async function loadMe(){try{const u=await api('/api/auth/me');window.currentUser=u;$('#userLabel').textContent=u.name+' · '+roleLabel(u.role);$('#usersNav').hidden=!['superadmin','owner','admin'].includes(u.role);$('#adminNav').hidden=u.role!=='superadmin'}catch{location.href='/login.html'}}
$('#logoutBtn').onclick=async()=>{await api('/api/auth/logout',{method:'POST'});location.href='/login.html'};
function modal(html){$('#modalContent').innerHTML=html;$('#modal').showModal()}
async function loadProducts(){const xs=await api('/api/products');$('#productsGrid').innerHTML=xs.length?xs.map(x=>`<article class="product-card"><div class="top"><b>${esc(x.name)}</b><span>${x.active?'Activo':'Inactivo'}</span></div><p>${esc(x.description||'Sin descripción')}</p><strong>${esc(x.currency)} ${Number(x.price).toLocaleString()}</strong><small>Stock/cupos: ${x.stock}</small><div class="actions"><button onclick='editProduct(${JSON.stringify(x)})' class="secondary">Editar</button><button onclick="deleteProduct(${x.id})" class="danger">Eliminar</button></div></article>`).join(''):'<p>No hay productos todavía.</p>'}
$('#newProduct').onclick=()=>productForm({name:'',description:'',price:0,currency:'COP',stock:0,active:true});
window.productForm=x=>{modal(`<h2>${x.id?'Editar':'Nuevo'} producto o servicio</h2><label>Nombre<input id="pName" value="${esc(x.name||'')}"></label><label>Descripción<textarea id="pDesc">${esc(x.description||'')}</textarea></label><div class="grid2"><label>Precio<input id="pPrice" type="number" value="${x.price||0}"></label><label>Moneda<input id="pCurrency" value="${esc(x.currency||'COP')}"></label></div><label>Stock o cupos<input id="pStock" type="number" value="${x.stock||0}"></label><label class="check"><input id="pActive" type="checkbox" ${x.active!==false?'checked':''}> Activo</label><div class="actions"><button type="button" id="saveProduct">Guardar</button><button value="cancel" class="secondary">Cancelar</button></div>`);setTimeout(()=>{$('#saveProduct').onclick=async()=>{const d={...x,name:$('#pName').value,description:$('#pDesc').value,price:Number($('#pPrice').value),currency:$('#pCurrency').value,stock:Number($('#pStock').value),active:$('#pActive').checked};await api('/api/products',{method:x.id?'PUT':'POST',body:JSON.stringify(d)});$('#modal').close();loadProducts();toast('Producto guardado')}},0)};
window.editProduct=x=>productForm(x);window.deleteProduct=async id=>{if(confirm('¿Eliminar este producto?')){await api('/api/products?id='+id,{method:'DELETE'});loadProducts()}};
async function loadAppointments(){const xs=await api('/api/appointments');$('#appointmentsTable').innerHTML=`<table class="table"><tr><th>Fecha</th><th>Cliente</th><th>Servicio</th><th>Estado</th><th></th></tr>${xs.map(x=>`<tr><td>${new Date(x.starts_at).toLocaleString()}</td><td><b>${esc(x.contact_name)}</b><small>${esc(x.contact_phone)}</small></td><td>${esc(x.service)}</td><td>${esc(x.status)}</td><td><button class="secondary" onclick='appointmentForm(${JSON.stringify(x)})'>Editar</button></td></tr>`).join('')}</table>`}
$('#newAppointment').onclick=()=>appointmentForm({duration_minutes:30,status:'Programada'});
window.appointmentForm=x=>{modal(`<h2>${x.id?'Editar':'Nueva'} cita</h2><label>Cliente<input id="aName" value="${esc(x.contact_name||'')}"></label><label>Teléfono<input id="aPhone" value="${esc(x.contact_phone||'')}"></label><label>Servicio<input id="aService" value="${esc(x.service||'')}"></label><label>Fecha y hora<input id="aStarts" type="datetime-local" value="${x.starts_at?x.starts_at.slice(0,16):''}"></label><div class="grid2"><label>Duración (min)<input id="aDuration" type="number" value="${x.duration_minutes||30}"></label><label>Estado<select id="aStatus">${['Programada','Confirmada','Completada','Cancelada','No asistió'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></label></div><label>Notas<textarea id="aNotes">${esc(x.notes||'')}</textarea></label><div class="actions"><button type="button" id="saveAppointment">Guardar</button><button value="cancel" class="secondary">Cancelar</button></div>`);setTimeout(()=>{$('#saveAppointment').onclick=async()=>{const raw=$('#aStarts').value;if(!raw)return toast('Selecciona fecha y hora');const d={...x,contact_name:$('#aName').value,contact_phone:$('#aPhone').value,service:$('#aService').value,starts_at:new Date(raw).toISOString(),duration_minutes:Number($('#aDuration').value),status:$('#aStatus').value,notes:$('#aNotes').value};await api('/api/appointments',{method:x.id?'PUT':'POST',body:JSON.stringify(d)});$('#modal').close();loadAppointments();toast('Cita guardada')}},0)};
async function loadUsers(){try{const xs=await api('/api/admin/users');$('#usersTable').innerHTML=`<table class="table"><tr><th>Nombre</th><th>Correo</th><th>Empresa</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr>${xs.map(x=>`<tr><td><input id="un${x.id}" value="${esc(x.name)}"></td><td>${esc(x.email)}</td><td><input id="uc${x.id}" value="${esc(x.company||'')}"></td><td><select id="ur${x.id}">${['superadmin','owner','admin','supervisor','agent'].map(r=>`<option ${x.role===r?'selected':''}>${r}</option>`).join('')}</select></td><td><input id="ua${x.id}" type="checkbox" ${x.active?'checked':''}></td><td><button onclick="saveUser(${x.id})">Guardar</button> <button class="danger" onclick="deleteUser(${x.id})">Eliminar</button></td></tr>`).join('')}</table>`}catch(e){$('#usersTable').textContent=e.message}}
window.saveUser=async id=>{await api('/api/admin/users',{method:'PUT',body:JSON.stringify({id,name:$('#un'+id).value,role:$('#ur'+id).value,company:$('#uc'+id).value,active:$('#ua'+id).checked})});toast('Usuario actualizado')};window.deleteUser=async id=>{if(confirm('¿Eliminar usuario?')){await api('/api/admin/users?id='+id,{method:'DELETE'});loadUsers()}};


function roleLabel(r){return ({superadmin:'Superadministrador',owner:'Propietario',admin:'Administrador',supervisor:'Supervisor',agent:'Asesor'})[r]||r}
async function loadBilling(){
 const [plans,e,cfg,payments]=await Promise.all([api('/api/plans'),api('/api/billing/entitlements'),api('/api/billing/config'),api('/api/billing/payments')]);
 $('#currentPlan').textContent=e.plan_name+' · '+(e.ends_at?('hasta '+new Date(e.ends_at).toLocaleDateString()):'activo');
 const usage=[['Usuarios',e.users_used,e.max_users],['Contactos',e.contacts_used,e.max_contacts],['Productos',e.products_used,e.max_products],['Automatizaciones',e.rules_used,e.max_rules],['Respuestas IA',e.ai_used,e.max_ai_responses]];
 $('#usageGrid').innerHTML=usage.map(x=>`<div class="stat"><b>${x[1]} / ${x[2]}</b><small>${x[0]}</small></div>`).join('');
 const extras={free:['1 agente IA','1 WhatsApp o 1 Telegram','2 campañas orgánicas','1 landing','1 grupo'],personal:['2 agentes IA','1 WhatsApp · 2 Telegram · 1 Messenger','10 campañas orgánicas','5 landings','5 grupos'],business:['5 agentes IA','3 WhatsApp · 5 Telegram · 3 Messenger','Campañas orgánicas, pagadas y combinadas','25 landings','30 grupos'],enterprise:['15 agentes IA','10 WhatsApp · 15 Telegram · 10 Messenger','Orquestador y auditoría','150 landings','200 grupos']}; $('#plansGrid').innerHTML=plans.map(p=>`<article class="plan-card ${p.code==='business'?'featured':''}"><span class="account-badge">${esc(p.name)}</span><h3>${esc(p.description)}</h3><div class="plan-price">${p.price_usdt===0?'Gratis':p.price_usdt+' USDT'}<small>${p.price_usdt?'/mes':''}</small></div><ul><li>${p.max_users} usuario(s)</li><li>${p.max_channels} conexión(es) aislada(s)</li><li>${p.max_contacts.toLocaleString()} contactos</li><li>${p.max_ai_responses.toLocaleString()} respuestas IA</li>${(extras[p.code]||[]).map(x=>`<li>${x}</li>`).join('')}</ul>${p.code===e.plan_code?'<button disabled>Plan actual</button>':(p.code==='free'?'<button disabled>Plan básico</button>':`<button onclick='buyPlan(${JSON.stringify(p)},${JSON.stringify(cfg)})'>Comprar con USDT</button>`)}</article>`).join('');
 $('#myPayments').innerHTML=payments.length?`<div class="admin-table-wrap"><table class="table"><tr><th>Fecha</th><th>Plan</th><th>Red</th><th>Monto</th><th>Transacción</th><th>Estado</th></tr>${payments.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString()}</td><td>${esc(x.plan_name)}</td><td>${esc(x.network)}</td><td>${x.amount_usdt} USDT</td><td><span class="mini">${esc(x.tx_hash)}</span></td><td class="status-${x.status}">${esc(x.status)}</td></tr>`).join('')}</table></div>`:'<p>No tienes pagos registrados.</p>';
}
window.buyPlan=(p,cfg)=>{modal(`<h2>Comprar plan ${esc(p.name)}</h2><p>Envía exactamente <b>${p.price_usdt} USDT</b> por una de las redes disponibles y después registra el hash.</p><div class="payment-box"><label>Red<select id="payNetwork"><option value="BEP20">BEP20 (BNB Smart Chain)</option><option value="TRC20">TRC20 (TRON)</option></select></label><div><small>Dirección de pago</small><div id="payWallet" class="wallet"></div></div><label>Hash de la transacción<input id="payHash" placeholder="0x... o hash TRON"></label><div class="notice">Verifica que estés enviando USDT por la red elegida. Los fondos enviados por otra red podrían perderse. El plan se activa después de la verificación del administrador.</div><div class="actions"><button type="button" id="submitPayment">Registrar pago</button><button value="cancel" class="secondary">Cancelar</button></div></div>`);const net=$('#payNetwork'),wallet=$('#payWallet');const draw=()=>wallet.textContent=net.value==='BEP20'?(cfg.bep20_address||'No configurada'):(cfg.trc20_address||'No configurada');net.onchange=draw;draw();$('#submitPayment').onclick=async()=>{try{await api('/api/billing/checkout',{method:'POST',body:JSON.stringify({plan_code:p.code,network:net.value,tx_hash:$('#payHash').value})});$('#modal').close();toast('Pago registrado para verificación');loadBilling()}catch(e){toast(e.message)}}}
async function loadAdmin(){
 const [o,p,s]=await Promise.all([api('/api/admin/overview'),api('/api/admin/payments'),api('/api/admin/subscriptions')]);
 $('#adminStats').innerHTML=[['Usuarios',o.users],['Usuarios activos',o.active_users],['Pagos pendientes',o.pending_payments],['Pagos aprobados',o.approved_payments],['Ventas USDT',o.revenue_usdt],['Suscripciones activas',o.active_subscriptions]].map(x=>`<div class="stat"><b>${x[1]}</b><small>${x[0]}</small></div>`).join('');
 $('#adminPayments').innerHTML=p.length?`<div class="admin-table-wrap"><table class="table"><tr><th>Usuario</th><th>Plan</th><th>Red/monto</th><th>Hash</th><th>Estado</th><th>Acción</th></tr>${p.map(x=>`<tr><td><b>${esc(x.user_name)}</b><small>${esc(x.user_email)}</small></td><td>${esc(x.plan_name)}</td><td>${esc(x.network)} · ${x.amount_usdt}</td><td><span class="mini">${esc(x.tx_hash)}</span></td><td class="status-${x.status}">${esc(x.status)}</td><td>${x.status==='pending'?`<button onclick="reviewPayment(${x.id},'approve')">Aprobar</button> <button class="danger" onclick="reviewPayment(${x.id},'reject')">Rechazar</button>`:''}</td></tr>`).join('')}</table></div>`:'<p>No hay pagos.</p>';
 $('#adminSubscriptions').innerHTML=`<div class="admin-table-wrap"><table class="table"><tr><th>Usuario</th><th>Empresa</th><th>Plan</th><th>Estado</th><th>Vence</th></tr>${s.map(x=>`<tr><td><b>${esc(x.user_name)}</b><small>${esc(x.user_email)}</small></td><td>${esc(x.company)}</td><td>${esc(x.plan_name)}</td><td>${esc(x.status)}</td><td>${new Date(x.ends_at).toLocaleDateString()}</td></tr>`).join('')}</table></div>`;
}
window.reviewPayment=async(id,action)=>{const note=prompt(action==='approve'?'Nota de aprobación (opcional)':'Motivo del rechazo');if(note===null)return;await api('/api/admin/payments',{method:'PUT',body:JSON.stringify({id,action,note})});toast(action==='approve'?'Plan activado':'Pago rechazado');loadAdmin()}

function esc(v=''){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
loadMe();loadDashboard();setInterval(()=>{loadDashboard();if($('#inbox').classList.contains('active')){loadConvs();if(activeChat)openChat(activeChat)}},8000);


// ── WORKTIC GROWTH ─────────────────────────────────────────────
let marketingLimits={},campaignAIPlan='';
$$('.growth-tabs button').forEach(b=>b.onclick=()=>{$$('.growth-tabs button,.growth-panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#growth-'+b.dataset.growth).classList.add('active');const k=b.dataset.growth;if(k==='calendar')loadMarketingContent();if(k==='creatives')loadCreatives();if(k==='forms')loadLeadForms();if(k==='leads')loadMarketingLeads()});
async function loadMarketing(){
 const [o,cs]=await Promise.all([api('/api/marketing/overview'),api('/api/marketing/campaigns')]);marketingLimits=o.limits||{};
 $('#marketingPlan').textContent=`${marketingLimits.plan||'free'} · ${marketingLimits.organic?'Orgánico':''}${marketingLimits.paid?' + Pagado':''}${marketingLimits.combined?' + Combinado':''}`;
 $('#marketingStats').innerHTML=[['Campañas',o.campaigns],['Programados',o.scheduled],['Leads',o.leads],['Formularios',o.forms],['Creativos',o.creatives]].map(x=>`<div class="stat"><b>${x[1]||0}</b><small>${x[0]}</small></div>`).join('');
 renderCampaigns(cs);
}
function renderCampaigns(xs){$('#campaignsGrid').innerHTML=xs.length?xs.map(x=>`<article class="product-card campaign-card"><span class="campaign-mode mode-${x.mode}">${esc(x.mode)}</span><b>${esc(x.name)}</b><p>${esc(x.objective)} · ${esc(x.product||'Sin producto')}</p><small>${esc(x.platforms)} → ${esc(x.destination)}</small><p><b>Presupuesto:</b> ${Number(x.budget_total||0).toLocaleString()} USDT</p><div class="actions"><button class="secondary" onclick="campaignDetails(${x.id})">Ver estrategia</button><button class="danger" onclick="deleteCampaign(${x.id})">Eliminar</button></div></article>`).join(''):'<p>No hay campañas. Crea la primera con el asistente de IA.</p>'}
$('#generateCampaign').onclick=async()=>{const f=$('#campaignWizard'),d=Object.fromEntries(new FormData(f));d.days=14;const b=$('#generateCampaign');b.disabled=true;$('#campaignAIPlan').textContent='Creando estrategia…';try{const x=await api('/api/marketing/generate',{method:'POST',body:JSON.stringify(d)});campaignAIPlan=x.plan;$('#campaignAIPlan').textContent=x.plan}catch(e){$('#campaignAIPlan').textContent=e.message}finally{b.disabled=false}};
$('#campaignWizard').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.budget_daily=Number(d.budget_daily||0);d.budget_total=Number(d.budget_total||0);d.ai_plan=campaignAIPlan;try{await api('/api/marketing/campaigns',{method:'POST',body:JSON.stringify(d)});e.target.reset();campaignAIPlan='';$('#campaignAIPlan').textContent='Campaña guardada. Puedes crear contenido y formularios relacionados.';toast('Campaña creada');loadMarketing()}catch(e){toast(e.message)}};
window.deleteCampaign=async id=>{if(confirm('¿Eliminar campaña?')){await api('/api/marketing/campaigns?id='+id,{method:'DELETE'});loadMarketing()}};
window.campaignDetails=async id=>{const xs=await api('/api/marketing/campaigns'),x=xs.find(a=>a.id===id);modal(`<h2>${esc(x?.name||'Campaña')}</h2><div class="growth-plan">${esc(x?.ai_plan||'Sin estrategia IA guardada')}</div><button value="cancel">Cerrar</button>`)};
async function loadMarketingContent(){const xs=await api('/api/marketing/content');$('#contentCalendar').innerHTML=xs.length?xs.map(x=>`<div class="calendar-item"><div class="date">${x.scheduled_at?new Date(x.scheduled_at).toLocaleString():'Sin programar'}</div><b>${esc(x.title||x.format)}</b><p>${esc(x.body)}</p><small>${esc(x.platform)} · ${esc(x.format)} · ${esc(x.status)}</small><div><button class="danger" onclick="deleteContent(${x.id})">Eliminar</button></div></div>`).join(''):'<p>No hay contenido programado.</p>'}
$('#newContent').onclick=()=>modal(`<h2>Nuevo contenido</h2><label>Campaña ID<input id="ctCampaign" type="number" value="0"></label><div class="grid2"><label>Plataforma<select id="ctPlatform"><option>facebook</option><option>instagram</option><option>messenger</option></select></label><label>Formato<select id="ctFormat"><option>post</option><option>reel</option><option>story</option><option>carousel</option></select></label></div><label>Título<input id="ctTitle"></label><label>Contenido<textarea id="ctBody" rows="6"></textarea></label><label>CTA<input id="ctCTA" placeholder="Escríbenos por WhatsApp"></label><label>Programar<input id="ctSchedule" type="datetime-local"></label><div class="actions"><button type="button" id="saveContent">Guardar</button><button value="cancel" class="secondary">Cancelar</button></div>`);document.addEventListener('click',async function h(ev){if(ev.target?.id!=='saveContent')return;document.removeEventListener('click',h);const raw=$('#ctSchedule').value;await api('/api/marketing/content',{method:'POST',body:JSON.stringify({campaign_id:Number($('#ctCampaign').value||0),platform:$('#ctPlatform').value,format:$('#ctFormat').value,title:$('#ctTitle').value,body:$('#ctBody').value,cta:$('#ctCTA').value,scheduled_at:raw?new Date(raw).toISOString():'',status:raw?'scheduled':'draft'})});$('#modal').close();loadMarketingContent();toast('Contenido guardado')});
window.deleteContent=async id=>{await api('/api/marketing/content?id='+id,{method:'DELETE'});loadMarketingContent()};
async function loadCreatives(){const xs=await api('/api/marketing/creatives');$('#creativeGrid').innerHTML=xs.length?xs.map(x=>`<article class="product-card"><b>${esc(x.name)}</b><p>${esc(x.kind)}</p>${x.url?`<a href="${esc(x.url)}" target="_blank">Abrir recurso</a>`:''}<small>${esc(x.notes)}</small></article>`).join(''):'<p>No hay creativos.</p>'}
$('#newCreative').onclick=()=>modal(`<h2>Agregar creativo</h2><label>Nombre<input id="crName"></label><label>Tipo<select id="crKind"><option>image</option><option>video</option><option>copy</option><option>document</option></select></label><label>URL del recurso<input id="crURL" placeholder="https://..."></label><label>Notas<textarea id="crNotes"></textarea></label><div class="actions"><button type="button" id="saveCreative">Guardar</button><button value="cancel" class="secondary">Cancelar</button></div>`);document.addEventListener('click',async function h2(ev){if(ev.target?.id!=='saveCreative')return;document.removeEventListener('click',h2);await api('/api/marketing/creatives',{method:'POST',body:JSON.stringify({name:$('#crName').value,kind:$('#crKind').value,url:$('#crURL').value,notes:$('#crNotes').value})});$('#modal').close();loadCreatives();toast('Creativo guardado')});
async function loadLeadForms(){const xs=await api('/api/marketing/forms');$('#leadFormsGrid').innerHTML=xs.length?xs.map(x=>`<article class="product-card"><b>${esc(x.name)}</b><p>${esc(x.headline)}</p><div class="public-link">${location.origin}/f/${x.tenant_id}/${x.slug}</div><button onclick="navigator.clipboard.writeText('${location.origin}/f/${x.tenant_id}/${x.slug}');toast('Enlace copiado')">Copiar enlace</button></article>`).join(''):'<p>No hay formularios.</p>'}
$('#newLeadForm').onclick=()=>modal(`<h2>Nuevo formulario / landing</h2><label>Nombre<input id="lfName"></label><label>Slug<input id="lfSlug" placeholder="valoracion-gratis"></label><label>Título público<input id="lfHeadline"></label><label>Descripción<textarea id="lfDesc"></textarea></label><label>Texto de consentimiento<textarea id="lfConsent">Autorizo el tratamiento de mis datos para recibir información relacionada con esta solicitud.</textarea></label><label>Mensaje de gracias<textarea id="lfThanks">Gracias. Pronto te contactaremos.</textarea></label><div class="actions"><button type="button" id="saveLeadForm">Crear</button><button value="cancel" class="secondary">Cancelar</button></div>`);document.addEventListener('click',async function h3(ev){if(ev.target?.id!=='saveLeadForm')return;document.removeEventListener('click',h3);await api('/api/marketing/forms',{method:'POST',body:JSON.stringify({name:$('#lfName').value,slug:$('#lfSlug').value,headline:$('#lfHeadline').value,description:$('#lfDesc').value,consent_text:$('#lfConsent').value,thank_you:$('#lfThanks').value})});$('#modal').close();loadLeadForms();toast('Formulario publicado')});
async function loadMarketingLeads(){const xs=await api('/api/marketing/leads');$('#marketingLeads').innerHTML=xs.length?`<div class="admin-table-wrap"><table class="table"><tr><th>Fecha</th><th>Lead</th><th>Fuente</th><th>Interés</th><th>Score</th><th>Consentimiento</th></tr>${xs.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString()}</td><td><b>${esc(x.name||'Sin nombre')}</b><small>${esc(x.phone)} · ${esc(x.email)}</small></td><td>${esc(x.source)}<small>${esc(x.utm_campaign||'')}</small></td><td>${esc(x.interest)}</td><td><span class="lead-score">${x.score}</span></td><td>${x.consent?'Sí':'No'}</td></tr>`).join('')}</table></div>`:'<p>Aún no hay leads capturados.</p>'}
$('#metaConnectInfo').onclick=()=>modal(`<h2>Activar Meta Ads</h2><ol><li>Verifica el negocio en Meta.</li><li>Configura Facebook Login for Business.</li><li>Solicita acceso avanzado a <code>ads_management</code>, <code>ads_read</code>, <code>leads_retrieval</code> y los permisos de páginas necesarios.</li><li>Implementa Embedded Signup para que cada cliente seleccione sus activos.</li><li>Configura webhooks para Lead Ads.</li><li>Prueba primero con usuarios y activos de desarrollo.</li></ol><div class="notice">Worktic nunca debe publicar ni aumentar presupuesto sin confirmación explícita del usuario.</div><button value="cancel">Cerrar</button>`);


